import{_ as e,c as o,o as t,a4 as a}from"./chunks/framework.BYxathSa.js";const g=JSON.parse('{"title":"Q11：useMemo 与 useCallback 详解","description":"","frontmatter":{},"headers":[],"relativePath":"react/q11.md","filePath":"react/q11.md","lastUpdated":null}'),s={name:"react/q11.md"},c=a('<h1 id="q11-usememo-与-usecallback-详解" tabindex="-1">Q11：<code>useMemo</code> 与 <code>useCallback</code> 详解 <a class="header-anchor" href="#q11-usememo-与-usecallback-详解" aria-label="Permalink to &quot;Q11：`useMemo` 与 `useCallback` 详解&quot;">​</a></h1><p>两者都用于缓存，避免不必要的计算或子组件重渲染。</p><ul><li><strong><code>useMemo(() =&gt; computeValue, deps)</code></strong>：缓存一个<strong>计算结果</strong>。只有 deps 变化时才重新计算，否则返回缓存的旧值。适用于昂贵计算或需要稳定引用的对象/数组。</li><li><strong><code>useCallback(fn, deps)</code></strong>：缓存一个<strong>函数引用</strong>。仅当 deps 变化时返回新的函数，配合 <code>React.memo</code> 可以避免子组件因函数引用变化而不必要地重渲染。</li></ul><p><strong>注意</strong>：不要提前过度优化，只在出现性能瓶颈或作为其他 Hook 的稳定依赖时才使用。</p>',4),r=[c];function l(n,d,_,u,i,m){return t(),o("div",null,r)}const h=e(s,[["render",l]]);export{g as __pageData,h as default};
